DROP TABLE IF EXISTS `deliveries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `deliveries` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_id` bigint NOT NULL,
  `carrier_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tracking_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shipping_fee` decimal(15,2) DEFAULT '0.00',
  `cod_amount` decimal(15,2) DEFAULT '0.00',
  `status` enum('PENDING','PICKED_UP','DELIVERING','DELIVERED','FAILED','RETURNED','CANCELLED') COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING',
  `note` text COLLATE utf8mb4_unicode_ci,
  `estimated_delivery_time` datetime DEFAULT NULL,
  `actual_delivery_time` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_deliveries_tracking` (`tracking_code`),
  KEY `fk_deliveries_order_idx` (`order_id`),
  CONSTRAINT `fk_deliveries_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

